export function initial(){return {version:3,energy:70,cap:100,coins:0,delivered:0,km:0,at:0,trip:null,owned:['cinnamon'],skin:'cinnamon',fleet:['starter'],train:'starter',upgrades:{battery:false,cargo:false,train:false,lantern:false,generator:false},baseline:null,resources:{gear:0,crystal:0,pollen:0},stats:{turbo:0,expeditions:0,cargos:[],visited:[0],snacks:0},claimed:[],expedition:null,collectCooldown:0}}
export function migrate(v){if(!v||![2,3].includes(v.version))return null;let s=v.version===2?{...initial(),...v,version:3,upgrades:{...initial().upgrades,...v.upgrades},baseline:null}:v;if(v.version===2){s.stats.visited=[...new Set([0,s.at])];if(s.delivered>0)s.stats.cargos=['seed']}if(v.version===2&&s.trip)s.trip={...s.trip,cargo:'seed',elapsed:0,gear:0,crystal:0,deadline:null,bonus:0};if(s.expedition)s.expedition=restoreExpedition(s.expedition,s);return validate(s)?s:null}
export function validate(s){if(!s||s.version!==3||!Number.isFinite(s.energy)||s.energy<0||!Number.isFinite(s.coins)||s.coins<0||!Number.isFinite(s.km)||s.km<0||!Number.isInteger(s.delivered)||s.delivered<0||!Number.isInteger(s.at)||s.at<0||s.at>=stations.length||![100,160].includes(s.cap)||s.energy>s.cap||!Array.isArray(s.owned)||!s.owned.includes('cinnamon')||!s.owned.includes(s.skin)||s.owned.some(x=>!skins.some(k=>k.id===x))||!s.upgrades||!Array.isArray(s.fleet)||!s.fleet.includes('starter')||!s.fleet.includes(s.train)||s.fleet.some(x=>!trains.some(t=>t.id===x))||!s.resources||Object.values(s.resources).some(x=>!Number.isFinite(x)||x<0)||!s.stats||!Array.isArray(s.stats.cargos)||!Array.isArray(s.stats.visited)||!Array.isArray(s.claimed)||!Number.isFinite(s.collectCooldown))return false;if(s.trip){let t=s.trip;if(!Number.isInteger(t.from)||!Number.isInteger(t.to)||t.from<0||t.to<0||t.from>=5||t.to>=5||t.from===t.to||!Number.isFinite(t.progress)||t.progress<0||t.progress>1||!Number.isFinite(t.cost)||t.cost<=0||!Number.isFinite(t.seconds)||t.seconds<1||!Number.isFinite(t.reward)||t.reward<0||!Number.isFinite(t.elapsed)||!cargos.some(c=>c.id===t.cargo))return false}if(s.expedition&&!validExpedition(s.expedition,s))return false;return true}
export const activeHamster=s=>skins.find(x=>x.id===s.skin)||skins[0],activeTrain=s=>trains.find(x=>x.id===s.train)||trains[0];
export function job(s,to,route,cargoId='seed'){let d=Math.abs(s.at-to),h=activeHamster(s),train=activeTrain(s),cargo=cargos.find(x=>x.id===cargoId)||cargos[0],bonus=h.id==='mint'&&cargo.id==='seed'?1.2:1;return {from:s.at,to,route,cargo:cargo.id,progress:0,elapsed:0,cost:Math.ceil((route==='eco'?25+d*5:38+d*6)*h.cost*train.cost*cargo.cost),seconds:Math.round((route==='eco'?27+d*5:18+d*4)*cargo.time/(h.speed*train.speed)),reward:Math.round((40+d*8+(s.upgrades.cargo?20:0))*h.reward*train.reward*cargo.pay*bonus),km:2+d*1.5,gear:(cargo.gear||0)+(h.id==='ember'&&cargo.id==='ore'?1:0),crystal:(cargo.crystal||0)+(h.id==='moon'&&cargo.id==='crystal'?1:0),deadline:cargo.deadline||null,bonus:0}}
export function dispatch(s,to,route,cargo='seed'){let c=cargos.find(x=>x.id===cargo);if(s.trip||s.at===to||s.energy<1||!Number.isInteger(to)||to<0||to>=5||s.delivered<stationUnlock[to]||!c||s.delivered<(c.unlock||0))return false;s.trip=job(s,to,route,cargo);return true}
export function tick(s,dt,producing,turbo){s.collectCooldown=Math.max(0,s.collectCooldown-dt);if(s.expedition&&!s.expedition.ready){s.expedition.remaining=Math.max(0,s.expedition.remaining-dt);if(s.expedition.remaining===0)s.expedition.ready=true}if(producing)s.energy=Math.min(s.cap,s.energy+dt*1.65*activeHamster(s).production*(s.upgrades.generator?1.2:1));if(!s.trip)return null;let t=s.trip;t.elapsed+=dt;if(s.energy<=0)return null;let delta=Math.min(1-t.progress,dt*(turbo?2:1)/t.seconds,s.energy/t.cost);s.energy=Math.max(0,s.energy-delta*t.cost);t.progress+=delta;if(t.progress>=.999999){t.bonus=t.deadline&&t.elapsed<=t.deadline?20:0;s.coins+=t.reward+t.bonus;s.resources.gear+=t.gear||0;s.resources.crystal+=t.crystal||0;s.delivered++;s.km+=t.km;s.at=t.to;if(!s.stats.cargos.includes(t.cargo))s.stats.cargos.push(t.cargo);if(!s.stats.visited.includes(t.to))s.stats.visited.push(t.to);s.trip=null;return t}return null}
export function turbo(s,rpm){let h=activeHamster(s);if(!s.trip||!Number.isFinite(rpm)||rpm<30||s.energy<h.turboCost)return 0;s.energy-=h.turboCost;s.stats.turbo++;return h.turboDuration}
export function measure(s,d,now=Date.now()){let m=d?.measurement,stamp=Date.parse(m?.observedAt),ttl=m?.staleAfterSeconds??120;if(!m||m.freshness!=='online'||!Number.isFinite(stamp)||stamp>now+10000||now-stamp>ttl*1000||!Number.isFinite(m.rpmMilli)||m.rpmMilli<0||!/^\d+$/.test(String(m.cumulativeWorkUnits))||!d.installationId||!m.counterEpoch){s.baseline=null;return null}let work=BigInt(m.cumulativeWorkUnits),id=d.installationId+':'+m.counterEpoch,b=s.baseline;if(b&&b.id===id&&work>=BigInt(b.work)){let delta=work-BigInt(b.work);s.energy=Math.min(s.cap,s.energy+Number(delta>10000n?10000n:delta)*.5*activeHamster(s).production*(s.upgrades.generator?1.2:1))}s.baseline={id,work:String(work)};return {rpm:m.rpmMilli/1000,stamp,ttl}}
export const upgradeInfo={battery:{title:'Deep-cell Battery',desc:'Battery capacity: 100 → 160 energy',price:80},cargo:{title:'Extra Cargo Wagon',desc:'+20 stars on new deliveries',price:110},train:{title:'Classic Blue Paint',desc:'Legacy livery for your starter locomotive',price:90},lantern:{title:'Firefly Lanterns',desc:'Bring a little evening magic to the valley',price:65},generator:{title:'Copper Generator',desc:'+20% wheel energy · requires 4 gears',price:100,gear:4}};
export function buyUpgrade(s,id){let u=upgradeInfo[id];if(!u||s.upgrades[id]||s.coins<u.price||s.resources.gear<(u.gear||0))return false;s.coins-=u.price;s.resources.gear-=u.gear||0;s.upgrades[id]=true;if(id==='battery')s.cap=160;return true}
export function buySkin(s,id){let k=skins.find(x=>x.id===id);if(!k||s.trip||s.expedition?.hamster===id)return false;if(!s.owned.includes(id)){if(s.coins<k.price)return false;s.coins-=k.price;s.owned.push(id)}s.skin=id;return true}
export function buyTrain(s,id){let t=trains.find(x=>x.id===id);if(!t||s.trip)return false;if(!s.fleet.includes(id)){if(s.coins<t.price)return false;s.coins-=t.price;s.fleet.push(id)}s.train=id;return true}
export const quests=[{id:'first',title:'First Shift',desc:'Complete 1 delivery',target:1,reward:30,value:s=>s.delivered},{id:'trio',title:'Cargo Specialist',desc:'Deliver 3 different cargo types',target:3,reward:80,value:s=>s.stats.cargos.length},{id:'turbo',title:'Wind on the Rails',desc:'Use boost 3 times',target:3,reward:50,value:s=>s.stats.turbo},{id:'fleet',title:'Railway Operator',desc:'Buy your first additional locomotive',target:1,reward:60,value:s=>s.fleet.length-1},{id:'explore',title:'Beyond the Valley',desc:'Reach Crystal Pass',target:1,reward:70,value:s=>s.stats.visited.includes(3)?1:0},{id:'crew',title:'Build a Crew',desc:'Own 3 hamsters',target:3,reward:100,value:s=>s.owned.length},{id:'expedition',title:'Expedition Crew',desc:'Collect 2 expedition rewards',target:2,reward:80,value:s=>s.stats.expeditions},{id:'ten',title:'Master Engineer',desc:'Complete 10 deliveries',target:10,reward:150,value:s=>s.delivered}];
export function claimQuest(s,id){let q=quests.find(x=>x.id===id);if(!q||s.claimed.includes(id)||q.value(s)<q.target)return false;s.claimed.push(id);s.coins+=q.reward;return true}
export function forage(s){if(s.collectCooldown>0)return false;s.collectCooldown=25;s.resources.pollen+=2;s.coins+=5;return true}
export function craftSnack(s){if(s.resources.pollen<4||s.energy>=s.cap)return false;s.resources.pollen-=4;s.energy=Math.min(s.cap,s.energy+30);s.stats.snacks++;return true}
export const expeditions=[{id:'forest',name:'Whispering Woods',seconds:60,energy:15,coins:35,gear:2,crystal:0},{id:'cave',name:'Crystal Caverns',seconds:90,energy:25,coins:50,gear:0,crystal:2,unlock:3}];
// Saved expedition labels and rewards are never trusted. Invalid trips are
// discarded without discarding the player's otherwise valid progress.
function restoreExpedition(value,s){
 if(!value||typeof value!=='object'||Array.isArray(value))return null;
 const def=expeditions.find(e=>e.id===value.id);
 if(!def||!s.owned?.includes(value.hamster)||value.hamster===s.skin||!Number.isFinite(value.remaining)||value.remaining<0||value.remaining>def.seconds)return null;
 return {...def,hamster:value.hamster,remaining:value.remaining,ready:value.remaining===0};
}
function validExpedition(value,s){
 const restored=restoreExpedition(value,s);
 return !!restored&&Object.keys(restored).every(key=>value[key]===restored[key]);
}
export function startExpedition(s,id,hamster){let e=expeditions.find(x=>x.id===id);if(!e||s.expedition||!s.owned.includes(hamster)||hamster===s.skin||s.energy<e.energy||s.delivered<(e.unlock||0))return false;s.energy-=e.energy;s.expedition={...e,hamster,remaining:e.seconds,ready:false};return true}
export function claimExpedition(s){let e=restoreExpedition(s.expedition,s);if(!e?.ready)return false;s.coins+=e.coins;s.resources.gear+=e.gear;s.resources.crystal+=e.crystal;s.stats.expeditions++;s.expedition=null;return e}
export function exchangeCrystal(s){if(s.resources.crystal<2)return false;s.resources.crystal-=2;s.coins+=45;return true}
